1	package dashboard
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"net/http"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"sync"
13	
14		"github.com/integrio-intropy/intropy-cli/internal/template"
15		"github.com/integrio-intropy/intropy-cli/internal/topology"
16	)
17	
18	// maxDocBytes caps how much of an enrichment document (AGENTS.md, README.md)
19	// the detail endpoint returns, so a huge file cannot bloat a response.
20	const maxDocBytes = 128 * 1024
21	
22	// apiServer holds the request-independent state for the JSON API.
23	type apiServer struct {
24		root    string
25		version string
26		topo    topologyProvider
27	
28		// topoMu guards the cached provider result. Fetching runs the hosts'
29		// graph verbs (a dotnet build on first run), so the result is computed
30		// once — on the first /api/topology request — and reused until an
31		// explicit refresh.
32		topoMu      sync.Mutex
33		topoLoaded  bool
34		topoEntries []topology.Entry
35		topoErrs    []string
36	}
37	
38	// topologyReport is the /api/topology payload: every declared topology plus
39	// the per-host failures the UI renders. Topologies is always an array (never
40	// null) even when empty.
41	type topologyReport struct {
42		Topologies []topologyEntry `json:"topologies"`
43		Errors     []string        `json:"errors,omitempty"`
44	}
45	
46	// topologyEntry is one system's declared topology plus the authored
47	// enrichment read from its directory: message descriptions keyed by connector
48	// name. The docs ride beside the Topology rather than inside it — the
49	// topology stays exactly what the host declared.
50	type topologyEntry struct {
51		topology.Entry
52		MessageDocs map[string]messageDoc `json:"messageDocs,omitempty"`
53	}
54	
55	// fileDoc is a text document surfaced in an integration's detail view.
56	type fileDoc struct {
57		Name    string `json:"name"`
58		Content string `json:"content"`
59	}
60	
61	// integrationSummary is a scaffold entry plus the coordinates the sidebar
62	// tree groups by: Name is the directory that carries the .intropy record.
63	// System is the name a sibling system-host scaffold declares for the
64	// directory's parent, falling back to the parent folder's name; Domain is the
65	// system's parent folder. Absent a host, System is empty when the integration
66	// sits directly under the workspace root, and Domain is empty when the
67	// system does.
68	type integrationSummary struct {
69		template.ScaffoldEntry
70		Name   string `json:"name"`
71		System string `json:"system,omitempty"`
72		Domain string `json:"domain,omitempty"`
73	}
74	
75	// integrationDetail is a single integration plus best-effort, on-disk
76	// enrichment. Every enrichment field is optional and absent when the
77	// corresponding file or directory does not exist.
78	type integrationDetail struct {
79		integrationSummary
80		Agents        *fileDoc        `json:"agents,omitempty"`
81		Readme        *fileDoc        `json:"readme,omitempty"`
82		Components    []DaprComponent `json:"components,omitempty"`
83		PipelineSteps []string        `json:"pipelineSteps,omitempty"`
84	}
85	
86	// newHandler wires the API routes and the SPA static handler onto a mux.
87	func newHandler(root, version string, topo topologyProvider) (http.Handler, error) {
88		api := &apiServer{root: root, version: version, topo: topo}
89		static, err := staticHandler()
90		if err != nil {
91			return nil, err
92		}
93	
94		mux := http.NewServeMux()
95		mux.HandleFunc("GET /api/health", api.health)
96		mux.HandleFunc("GET /api/integrations", api.listIntegrations)
97		mux.HandleFunc("GET /api/integrations/{path...}", api.getIntegration)
98		mux.HandleFunc("GET /api/flow", api.flow)
99		mux.HandleFunc("GET /api/topology", api.topologies)
100		mux.HandleFunc("POST /api/topology/refresh", api.refreshTopologies)
101		mux.Handle("/", static)
102		return mux, nil
103	}
104	
105	func (s *apiServer) health(w http.ResponseWriter, _ *http.Request) {
106		writeJSON(w, http.StatusOK, map[string]string{
107			"status":  "ok",
108			"version": s.version,
109		})
110	}
111	
112	// listIntegrations mirrors `int list -o json` — the same scaffold entries in
113	// the same order — with the derived name/system fields added on top and each
114	// Path normalized to a root-relative identifier. The response is always an
115	// array (never null) even when empty.
116	func (s *apiServer) listIntegrations(w http.ResponseWriter, _ *http.Request) {
117		entries, systems := s.scan()
118		summaries := make([]integrationSummary, 0, len(entries))
119		for _, e := range entries {
120			summaries = append(summaries, s.summarize(e, systems))
121		}
122		writeJSON(w, http.StatusOK, summaries)
123	}
124	
125	// scan splits the workspace's scaffold entries for the API: the integration
126	// blocks to catalog, plus the declared systems keyed by their root directory
127	// (the directory holding a system-host scaffold). Support projects — the host
128	// and its shared contracts library — are infrastructure the system view
129	// already represents, not integrations to list.
130	func (s *apiServer) scan() (blocks []template.ScaffoldEntry, systems map[string]string) {
131		entries, _ := template.ListScaffolds(s.root)
132		systems = map[string]string{}
133		for _, e := range entries {
134			if e.Role == template.RoleSystemHost {
135				systems[filepath.Clean(filepath.Dir(e.Path))] = systemName(e)
136			}
137		}
138		blocks = entries[:0]
139		for _, e := range entries {
140			if e.Role == template.RoleSystemHost || e.Role == template.RoleSharedLibrary {
141				continue
142			}
143			blocks = append(blocks, e)
144		}
145		return blocks, systems
146	}
147	
148	// systemName is the name a system-host scaffold declares for its system
149	// (the template's `name` value, recorded at `sys create`), falling back to
150	// the host's parent directory name.
151	func systemName(host template.ScaffoldEntry) string {
152		if name, ok := host.Values["name"].(string); ok && name != "" {
153			return name
154		}
155		dir := filepath.Dir(host.Path)
156		if abs, err := filepath.Abs(dir); err == nil {
157			dir = abs
158		}
159		return filepath.Base(dir)
160	}
161	
162	// summarize derives an entry's tree coordinates from its path and the
163	// declared systems. A sibling system-host makes membership explicit: its
164	// declared name wins over the folder-derived one and applies even directly
165	// under the workspace root (where no folder-derived system exists).
166	// Otherwise the workspace root itself never counts as a system or domain, so
167	// an integration scaffolded at the root has neither and one directly under
168	// the root has a system but no domain. The served Path is made root-relative
169	// so it is a stable, URL-safe identifier regardless of whether the command
170	// was given a relative or absolute root (an absolute path would otherwise
171	// break detail lookups).
172	func (s *apiServer) summarize(e template.ScaffoldEntry, systems map[string]string) integrationSummary {
173		sum := integrationSummary{ScaffoldEntry: e, Name: filepath.Base(e.Path)}
174		sum.Path = s.relPath(e.Path)
175		path, root := filepath.Clean(e.Path), filepath.Clean(s.root)
176		parent := filepath.Dir(path)
177		if declared, ok := systems[parent]; ok && path != root {
178			sum.System = declared
179			if grand := filepath.Dir(parent); parent != root && grand != root {
180				sum.Domain = filepath.Base(grand)
181			}
182			return sum
183		}
184		if path == root || parent == root {
185			return sum
186		}
187		sum.System = filepath.Base(parent)
188		if grand := filepath.Dir(parent); grand != root {
189			sum.Domain = filepath.Base(grand)
190		}
191		return sum
192	}
193	
194	// relPath turns an entry's on-disk path into the root-relative, slash-separated
195	// identifier used in API responses and URLs. It falls back to the cleaned path
196	// so a value is always produced even if Rel fails (e.g. differing volumes).
197	func (s *apiServer) relPath(p string) string {
198		if rel, err := filepath.Rel(s.root, p); err == nil {
199			return filepath.ToSlash(rel)
200		}
201		return filepath.ToSlash(filepath.Clean(p))
202	}
203	
204	// flow returns every integration enriched with the pipeline steps and Dapr
205	// components the flow canvas draws, so the whole graph loads in one request.
206	// It reuses integrationDetail but leaves the document fields (agents/readme)
207	// nil — the canvas nodes do not render them.
208	func (s *apiServer) flow(w http.ResponseWriter, _ *http.Request) {
209		entries, systems := s.scan()
210		nodes := make([]integrationDetail, 0, len(entries))
211		for _, e := range entries {
212			dir := e.Path
213			nodes = append(nodes, integrationDetail{
214				integrationSummary: s.summarize(e, systems),
215				Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
216				PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
217			})
218		}
219		writeJSON(w, http.StatusOK, nodes)
220	}
221	
222	// topologies returns every system topology declared by a host's graph verb,
223	// each Path normalized to the same root-relative identifier integration
224	// paths use, so the flow canvas can match a topology to the integrations
225	// living beside its host. The provider result is cached after the first
226	// request (the verb builds the host); POST /api/topology/refresh recomputes.
227	func (s *apiServer) topologies(w http.ResponseWriter, r *http.Request) {
228		writeJSON(w, http.StatusOK, s.topologyReport(r.Context(), false))
229	}
230	
231	// refreshTopologies recomputes the topology cache by re-running every host's
232	// graph verb, then returns the fresh report.
233	func (s *apiServer) refreshTopologies(w http.ResponseWriter, r *http.Request) {
234		writeJSON(w, http.StatusOK, s.topologyReport(r.Context(), true))
235	}
236	
237	// topologyReport assembles the /api/topology payload: the cached provider
238	// result plus the message docs read fresh from disk on every request, so an
239	// edited doc shows up on a browser refresh without re-running the hosts'
240	// graph verbs.
241	func (s *apiServer) topologyReport(ctx context.Context, force bool) topologyReport {
242		entries, errs := s.cachedTopologies(ctx, force)
243		report := topologyReport{
244			Topologies: make([]topologyEntry, 0, len(entries)),
245			Errors:     append([]string(nil), errs...),
246		}
247		for _, e := range entries {
248			docs, docErrs := s.messageDocs(e)
249			report.Topologies = append(report.Topologies, topologyEntry{Entry: e, MessageDocs: docs})
250			report.Errors = append(report.Errors, docErrs...)
251		}
252		return report
253	}
254	
255	// cachedTopologies returns the provider result — computed on first use or
256	// when force is set, reused otherwise. Concurrent requests share one
257	// computation. Entry paths are normalized to root-relative identifiers.
258	func (s *apiServer) cachedTopologies(ctx context.Context, force bool) ([]topology.Entry, []string) {
259		s.topoMu.Lock()
260		defer s.topoMu.Unlock()
261		if !s.topoLoaded || force {
262			entries, errs := s.topo(ctx)
263			s.topoEntries = make([]topology.Entry, 0, len(entries))
264			for _, e := range entries {
265				e.Path = s.relPath(e.Path)
266				s.topoEntries = append(s.topoEntries, e)
267			}
268			s.topoErrs, s.topoLoaded = errs, true
269		}
270		return s.topoEntries, s.topoErrs
271	}
272	
273	// messageDocs reads the authored connector payload descriptions beside a
274	// system, keyed by connector name. A doc naming a connector the topology does
275	// not declare is surfaced as an error and withheld — never guessed around.
276	// Error messages carry the doc's workspace-relative path.
277	func (s *apiServer) messageDocs(e topology.Entry) (map[string]messageDoc, []string) {
278		docs, errs := readMessageDocs(filepath.Join(s.root, filepath.FromSlash(e.Path)))
279		prefix := ""
280		if e.Path != "." {
281			prefix = e.Path + "/"
282		}
283		for i, msg := range errs {
284			errs[i] = prefix + msg
285		}
286		known := map[string]bool{}
287		for _, c := range e.Connectors {
288			known[c.Name] = true
289		}
290		var unknown []string
291		for name := range docs {
292			if !known[name] {
293				unknown = append(unknown, name)
294				delete(docs, name)
295			}
296		}
297		sort.Strings(unknown)
298		for _, name := range unknown {
299			errs = append(errs, fmt.Sprintf("%s%s/%s.md: no connector %q declared by system %q",
300				prefix, messagesDirName, name, name, e.System))
301		}
302		if len(docs) == 0 {
303			docs = nil
304		}
305		return docs, errs
306	}
307	
308	func (s *apiServer) getIntegration(w http.ResponseWriter, r *http.Request) {
309		want := strings.Trim(r.PathValue("path"), "/")
310		// An integration at the workspace root has the identifier "." (see
311		// relPath), but a browser strips the "." segment from /api/integrations/.
312		// so it arrives empty — treat the two as the same request.
313		if want == "" {
314			want = "."
315		}
316		entries, systems := s.scan()
317		for _, e := range entries {
318			if s.relPath(e.Path) == want {
319				writeJSON(w, http.StatusOK, s.enrich(e, systems))
320				return
321			}
322		}
323		writeError(w, http.StatusNotFound, "integration not found: "+want)
324	}
325	
326	// enrich reads optional on-disk context for an integration. The entry's Path
327	// is already usable from the process working directory (see ListScaffolds), so
328	// it doubles as the project directory.
329	func (s *apiServer) enrich(e template.ScaffoldEntry, systems map[string]string) integrationDetail {
330		dir := e.Path
331		return integrationDetail{
332			integrationSummary: s.summarize(e, systems),
333			Agents:             readDoc(dir, "AGENTS.md"),
334			Readme:             readDoc(dir, "README.md"),
335			Components:         readComponents(filepath.Join(dir, "local", "dapr-components")),
336			PipelineSteps:      listNames(filepath.Join(dir, "src", "Process", "Steps")),
337		}
338	}
339	
340	// readDoc returns the named text file's (possibly truncated) contents, or nil
341	// if it is absent or unreadable.
342	func readDoc(dir, name string) *fileDoc {
343		data, err := os.ReadFile(filepath.Join(dir, name))
344		if err != nil {
345			return nil
346		}
347		if len(data) > maxDocBytes {
348			data = data[:maxDocBytes]
349		}
350		return &fileDoc{Name: name, Content: string(data)}
351	}
352	
353	// listNames returns the sorted base names of the files directly under dir, or
354	// nil if dir is absent or unreadable.
355	func listNames(dir string) []string {
356		ents, err := os.ReadDir(dir)
357		if err != nil {
358			return nil
359		}
360		var names []string
361		for _, ent := range ents {
362			if !ent.IsDir() {
363				names = append(names, ent.Name())
364			}
365		}
366		sort.Strings(names)
367		return names
368	}
369	
370	func writeJSON(w http.ResponseWriter, status int, v any) {
371		w.Header().Set("Content-Type", "application/json; charset=utf-8")
372		w.WriteHeader(status)
373		enc := json.NewEncoder(w)
374		enc.SetIndent("", "  ")
375		_ = enc.Encode(v)
376	}
377	
378	func writeError(w http.ResponseWriter, status int, msg string) {
379		writeJSON(w, status, map[string]string{"error": msg})
380	}
381

